function OverseaRenovaAestheticsLevelupPopup:RefreshUI(params)
    self.params = params
    local data = params.data
    CfUtils.FillText(self.TextNumberOld,data.curNum)
    CfUtils.FillText(self.TextNumberNew,data.nextNum)
    local MaidCoffeeUtils   = import("Game.MaidCoffee.MaidCoffeeUtils")
    local vo = MaidCoffeeUtils.GetAestheticsVo(data.curIndex)
    local nextVo = MaidCoffeeUtils.GetAestheticsVo(data.nextIndex)
    self:SetNumShow(self.TipPointOld,vo)
    self:SetNumShow(self.TipPointOldNew,nextVo)

    ---@type MaidCoffeeSkillVo
    local skillVo = MaidCoffeeUtils.GetMaidCoffeeSkillInfoVo(nextVo.additionId)
    if skillVo then
        local desc = MaidCoffeeUtils.FillCoffeeSkillDescription(skillVo.decr, nextVo.additionNum,nil,nextVo.percentage)
        CfUtils.FillText(self.TextDesc,desc)
    end
end

function OverseaRenovaAestheticsLevelupPopup:SetNumShow(txt,vo)
    local numStr = tonumber(vo.additionNum[2])
    CfUtils.FillText(txt,numStr)
end

